def calculate_tax(subtotal, rate=0.08):
    """Return tax rounded to 2 decimal places."""
    return round(subtotal * rate, 2)

print("Order 1 tax: $", calculate_tax(100))
print("Order 2 tax: $", calculate_tax(250, 0.10))

def min_and_max(numbers):
    return min(numbers), max(numbers)

lowest, highest = min_and_max([5, 2, 9, 1])
print(f"Lowest: {lowest}, Highest: {highest}")

def clean_username(raw_name):
    """Strip whitespace and lowercase username."""
    return raw_name.strip().lower()

print(clean_username("  DevUser12  "))

