def clamp(val, min_val, max_val):
    if val < min_val:
        return min_val
    if val > max_val:
        return max_val
    return val
print(clamp(15, 0, 10))

def check_password(pwd):
    if len(pwd) < 8:
        return 'Too short'
    if pwd.isalpha():
        return 'Needs numbers'
    return 'Strong'
print(check_password("secret123"))
